import RNA, sys, random, math, time, multiprocessing as mp
target = "((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..))."
n=len(target)
def pairs_of(ss):
    p=[-1]*n; st=[]
    for i,c in enumerate(ss):
        if c=='(':st.append(i)
        elif c==')':
            j=st.pop();p[i]=j;p[j]=i
    return p
tp=pairs_of(target)
def fold(seq):
    fc=RNA.fold_compound(seq); ss,mfe=fc.mfe(); return ss,mfe
def bpd(seq):
    ss,_=fold(seq); fp=pairs_of(ss)
    return sum(1 for i in range(n) if fp[i]!=tp[i]), ss

start=sys.argv[1]
def run(seed):
    random.seed(seed)
    cur=list(start)
    cs,_=bpd(''.join(cur))
    best=cur[:]; bs=cs
    T=1.5
    t0=time.time()
    while time.time()-t0<110:
        r=random.random()
        cand=cur[:]
        if r<0.6:
            _,ss=fold(''.join(cur)); fp=pairs_of(ss)
            diffs=[i for i in range(n) if fp[i]!=tp[i]]
            if diffs:
                i=random.choice(diffs)
                if tp[i]>=0:
                    j=tp[i]; cand[i]='G'; cand[j]='C'
                else:
                    j=fp[i] if fp[i]>=0 else -1
                    cand[i]='A'
                    if j>=0 and random.random()<0.5: cand[j]='A'
        else:
            i=random.randint(0,n-1)
            nb=random.choice([c for c in 'AUCG' if c!=cur[i]]); cand[i]=nb
            if tp[i]>=0 and random.random()<0.3:
                j=tp[i]; cand[j]=random.choice([c for c in 'AUCG' if c!=cur[j]])
        sc,_=bpd(''.join(cand))
        delta=sc-cs
        if delta<=0 or random.random()<math.exp(-delta/max(T,0.01)):
            cur=cand; cs=sc
            if sc<bs:
                bs=sc; best=cand[:]
                if bs==0: return 0,''.join(best)
        T*=0.9997
        if T<0.05: T=1.5
    return bs,''.join(best)

if __name__=='__main__':
    start=sys.argv[1]
    nproc=150
    with mp.Pool(nproc) as pool:
        res=pool.map(run, list(range(nproc)))
    res.sort(key=lambda x:x[0])
    sys.stderr.write(f"BEST={res[0][0]}\n")
    print(res[0][1])
    with open('/tmp/best2.txt','w') as f: f.write(res[0][1])

